from collections import deque

def trigger_pts(grid):
    h,w=len(grid),len(grid[0]); seen=set(); boxes=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=3 or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); pts=[]
        while q:
          x,y=q.pop(); pts.append((x,y))
          for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
            if 0<=nx<h and 0<=ny<w and grid[nx][ny]==3 and (nx,ny) not in seen:
              seen.add((nx,ny)); q.append((nx,ny))
        boxes.append((min(x for x,y in pts),max(x for x,y in pts),min(y for x,y in pts),max(y for x,y in pts)))
    return sorted((r,c) for r in range(h) for c in range(w) if grid[r][c]==2 and any(a<=r<=b and c0<=c<=c1 for a,b,c0,c1 in boxes)), boxes

def transform(grid):
    out=[row[:] for row in grid]; active=trigger_pts(grid)[0]; active_set=set(active)
    for r,c in active:
      for i in range(max(0,r-1),min(len(grid),r+2)):
        for j in range(max(0,c-1),min(len(grid[0]),c+2)):
          if (i,j) not in active_set: out[i][j]=1
    return out
